 (* This is the main code. We read the file into the session if not already
    done, we apply the split_goal transformation when needed, and we schedule
    the first VC of all check. When done, we save the session.
 *)

let _ =
  if Gnat_config.debug then Debug.(set_flag (lookup_flag "gnat_ast"));
  Debug.set_flag Pinterp.debug_disable_builtin_mach;
  Debug.set_flag Debug.stats;
  List.iter Introduction.add_unique_prefix
    ["GP_Check:"; "GP_Pretty_Ada:"; "GP_Shape:"; "GP_Sloc:";
     "GP_Already_Proved"; "GP_Inline"; "GP_Inlined"];
  ( try
      let log = Sys.getenv "GNATWHY3LOG" in
      let out = open_out_gen [Open_text; Open_creat; Open_append] 0o666 log in
      let fmt = Format.formatter_of_out_channel out in
      Debug.set_debug_formatter fmt;
      Format.fprintf fmt "@.@.===== %s@." Gnat_config.filename;
      Loc.set_warning_hook (fun ?loc:_ line -> Format.fprintf fmt "%s@." line)
    with Not_found -> () );
  try
    let c = Debug.Stats.record_timing "gnatwhy3.init" Gnat_checks.init_cont in
    (* This has to be done after initialization of controller. Otherwise we
       don't have session. *)
    Sys.set_signal Sys.sigint (Sys.Signal_handle (save_session_and_exit c));
    begin match Gnat_config.proof_mode with
    | Gnat_config.Progressive
    | Gnat_config.Per_Path
    | Gnat_config.Per_Check ->
        Debug.Stats.record_timing "gnatwhy3.register_vcs"
         (fun () -> C.iter_subps c (normal_handle_one_subp c));
        if Gnat_config.replay then begin
          C.replay c (*;
          Gnat_checks.do_scheduled_jobs (fun _ _ -> ());*)
        end else begin
          Debug.Stats.record_timing "gnatwhy3.schedule_vcs"

let mk_comment_attr = function
  | No_symbol -> None
  | Symbol s -> Some (mk_str ("GNAT-comment:"^s))

module Curr = struct

  let loc_ref = ref No_location
  let marker_ref = ref No_symbol

  let with_ curr f =
    let push (loc, marker) =
      loc_ref := loc;
      marker_ref := marker in
    let pop () =
      let loc, marker = No_location, No_symbol in
      loc_ref := loc;
      marker_ref := marker in
    push curr;
    let res = f () in
    pop ();
    res

  let mk_attrs () =
    match !loc_ref with
    | No_location ->
        []
    | Source_ptr r ->
        let filename =
          match !marker_ref with
          | No_symbol -> r.filename
          | Symbol s -> "'@"^s^"@'"^r.filename in
        Option.(to_list (mk_location (Source_ptr {r with filename})))

let mk_binder_of_identifier attrs pty node =
  let id =
    let err = conversion_error node.info.id "qualified or empty identifier" in
    force_one err (mk_idents_of_identifier ~notation:None attrs node) in
  get_pos (), Some id, false, Some pty in
let mk_identifier_labels (node : identifier_id) =
  let Identifier r = node.desc in
  List.filter_map mk_label r.labels in

let mk_record_binder (node : record_binder_id) =
  let Record_binder r = node.desc in
  let ident =
    let name = Opt.force (conversion_error node.info.id "missing name") r.name in
    let idents = mk_idents_of_identifier ~notation:None (List.filter_map mk_label r.labels) name in
    force_one (conversion_error node.info.id "quantified or empty name") idents in
  let pty = mk_pty_of_type r.arg_type in
  {f_ident = ident; f_pty = pty; f_mutable = r.is_mutable;
   f_ghost = false; f_loc = get_pos ()}

let loc_counter = ref 0

let get_pos ?loc () = match loc with
  | Some loc ->
      loc
  | None ->
      incr loc_counter;
      let line = !loc_counter in
      Loc.user_position "<dummy>" line 0 line 0

let mk_ident attrs s = {
  id_str = s;
  id_ats = attrs;
  id_loc = get_pos ();
}

let mk_qualid l =
  let rec aux l =
    match l with
    | [] -> failwith "mk_qualid"
    | [x] -> Qident x
    | x::r -> Qdot (aux r, x)
  in
  aux (List.rev l)

let mk_qualid' l =
  mk_qualid (List.map (mk_ident []) l)

let mk_expr ?loc e =
  { expr_desc = e; expr_loc = get_pos ?loc () }

let mk_term ?loc t =
  { term_desc = t; term_loc = get_pos ?loc () }

let mk_pat ?loc p =
  { pat_desc = p; pat_loc = get_pos ?loc () }

let rec qualid_equal a b =
  match a, b with
  | Qident a, Qident b -> a.id_str = b.id_str
  | Qdot (a_prefix, a_id), Qdot (b_prefix, b_id) ->
      qualid_equal a_prefix b_prefix && a_id.id_str = b_id.id_str
  | _ -> false

